void IEffect::initializeEffect(const SferaEffectInitializeContext&) { std::abort(); }
void IEffect::updateEffect(const SferaEffectUpdateContext&) { std::abort(); }
void IEffect::queryEffectState(const SferaEffectQueryContext&) {
}
