void CLightEffect::setParameter(const SferaEffectParameter* parameters, std::size_t count) {
    if (parameters == nullptr) return;
    for (std::size_t index = 0u; index < count; ++index) {
        const SferaEffectParameter& parameter = parameters[index];
        if (parameter.value == nullptr) continue;
        switch (parameter.id) {
            case 1u: {
                const auto* rgb = static_cast<const std::uint16_t*>(parameter.value);
                color[0] = rgb[0];
                color[1] = rgb[1];
                color[2] = rgb[2];
                break;
            }
            case 2u: radius = *static_cast<const float*>(parameter.value);
            break;
            case 3u: brightness_jitter = static_cast<float>(*static_cast<const std::uint8_t*>(parameter.value)) / 100.0f;
            break;
            case 4u: brightness_frequency = *static_cast<const std::uint8_t*>(parameter.value);
            break;
            default: break;
        }
    }
}
void CLightEffect::destroyEffect(bool free_storage) { g_sfera_light_runtime.release(light_index); light_index = -1; registered = false; IEffect::destroyEffect(free_storage); }
IOutputDevice::IOutputDevice() { buffer = static_cast<char*>(g_sfera_std_allocator.allocate(buffer_capacity, 0u)); if (buffer != nullptr) buffer[0] = '\0'; }
IOutputDevice::~IOutputDevice() { g_sfera_std_allocator.deallocate(buffer); buffer = nullptr; }
COutputLogDevice::~COutputLogDevice() { g_sfera_std_allocator.deallocate(filename); filename = nullptr; }
void COutputLogDevice::setFilename(const char* path) {
    g_sfera_std_allocator.deallocate(filename);
    filename = nullptr;
    if (path == nullptr || *path == '\0') return;
    const std::size_t length = std::strlen(path) + 1u;
    filename = static_cast<char*>(g_sfera_std_allocator.allocate(length, 0u));
    if (filename == nullptr) return;
    std::memcpy(filename, path, length);
    FILE* file = nullptr;
    if (fopen_s(&file, filename, "wt") == 0 && file != nullptr) {
        std::time_t now = std::time(nullptr);
        char created_at[32]{};
        if (ctime_s(created_at, sizeof(created_at), &now) != 0) created_at[0] = '\0';
        std::fprintf(file, "Sphere log file\nCreated: %s\n", created_at);
        std::fclose(file);
    }
}
void COutputLogDevice::write(const char* text) { if (filename == nullptr || text == nullptr) return; FILE* file = nullptr; if (fopen_s(&file, filename, "a+t") == 0 && file != nullptr) { std::fprintf(file, "- %s\n", text); std::fclose(file); } }
void CSphereError::write(const char* text) {
    if (g_sfera_view_motion_runtime.initialized) { set_system_cursor_visibility(true); ::MessageBoxA(main_window_handle(), "Reenter in exit_msg detected!", "Error", MB_OK | MB_ICONERROR); ::ExitProcess(0u); }
    g_sfera_view_motion_runtime.initialized = true;
    std::snprintf(g_sfera_error_message_scratch_runtime.fatal_message, sizeof(g_sfera_error_message_scratch_runtime.fatal_message), "ServerN=%d  %s", static_cast<int>(g_sfera_recovered_static_runtime.server_number), text == nullptr ? "" : text);
    set_system_cursor_visibility(true);
    ::MessageBoxA(main_window_handle(), g_sfera_error_message_scratch_runtime.fatal_message, "Error", MB_OK | MB_ICONERROR);
    ::ExitProcess(0u);
}
void GrassMapMngr::loadGrassMap(std::int32_t column, std::int32_t row, std::span<std::uint8_t> destination) {
    if (destination.empty()) return;
    char filename[64]{};
    std::snprintf(filename, sizeof(filename), "Landscape\\GrassMap\\GrassMap_%02d_%02d.bin", column, row);
    std::ifstream stream;
    for (const std::string& path : g_sfera_files.candidatePaths(filename, true)) { stream.open(path, std::ios::binary); if (stream.is_open()) break; stream.clear(); }
    if (stream.is_open()) stream.read(reinterpret_cast<char*>(destination.data()), static_cast<std::streamsize>(destination.size()));
}
void CItem::resetItem() {}
void CItem::releaseItem() {}
std::int32_t CItemListCommonItem::initialize(std::int32_t minimum, std::int32_t, std::uint32_t mode, const char* list_name, std::uint32_t parameter) {
    minimum_items = std::max(minimum, 0);
    capacity = 30u;
    item_count = 0u;
    list_mode = mode;
    item_parameter = parameter;
    std::memset(name, 0, sizeof(name));
    if (list_name != nullptr) std::memcpy(name, list_name, std::min<std::size_t>(std::strlen(list_name), sizeof(name) - 1u));
    item_index.clear();
    item_storage.clear();
    try { item_storage.resize(capacity); } catch (const std::bad_alloc&) { capacity = 0; return -14; }
    return 0;
}
std::int32_t CBaseManagerCommonItem::initialize(std::int32_t minimum, std::int32_t, std::uint32_t mode, const char* list_name, std::uint32_t parameter) {
    minimum_items = std::max(minimum, 0);
    capacity = 30u;
    item_count = 0u;
    list_mode = mode;
    item_parameter = parameter;
    std::memset(name, 0, sizeof(name));
    if (list_name != nullptr) std::memcpy(name, list_name, std::min<std::size_t>(std::strlen(list_name), sizeof(name) - 1u));
    item_index.clear();
    list_storage.clear();
    try { list_storage.resize(capacity); } catch (const std::bad_alloc&) { capacity = 0; return -14; }
    return 0;
}
CCommonItem* CItemListCommonItem::findStoredItem(const CItem* key) {
    if (key == nullptr) return nullptr;
    auto& index = item_index;
    CCommonItem* storage = item_storage.data();
    if (storage == nullptr) return nullptr;
    const auto found = index.find(key->name);
    return found == index.end() || found->second >= capacity ? nullptr : storage + found->second;
}
CCommonItem* CItemListCommonItem::firstItem() {
    CCommonItem* storage = item_storage.data();
    if (storage == nullptr) { iterator_index = -1; return nullptr; }
    for (std::size_t index = 0u; index < capacity; ++index) if (storage[index].active == 1u) { iterator_index = index; return storage + index; }
    iterator_index = -1;
    return nullptr;
}
CCommonItem* CItemListCommonItem::nextItem() {
    CCommonItem* storage = item_storage.data();
    if (storage == nullptr || iterator_index < 0) return nullptr;
    for (std::size_t index = static_cast<std::size_t>(iterator_index) + 1u; index < capacity; ++index) if (storage[index].active == 1u) { iterator_index = index; return storage + index; }
    return nullptr;
}
std::int32_t CItemListCommonItem::addItem(const CCommonItem* item) {
    if (item == nullptr) return -3;
    const CCommonItem value = *item;
    if (item_count == capacity) {
        const std::size_t growth = std::max<std::size_t>(capacity / 4u, 50u);
        if (capacity > std::size_t{std::numeric_limits<std::ptrdiff_t>::max()} / sizeof(CCommonItem) - growth) return -20;
        try { item_storage.resize(capacity + growth); } catch (const std::bad_alloc&) { return -20; }
        capacity += growth;
    }
    auto& index = item_index;
    CCommonItem* storage = item_storage.data();
    if (storage == nullptr) return -3;
    const auto found = index.find(value.name);
    if (found != index.end()) {
        const auto existing_slot = found->second;
        if (existing_slot >= capacity) return -105;
        CCommonItem* destination = storage + existing_slot;
        *destination = value;
        destination->active = true;
        return -105;
    }
    std::size_t slot = 0u;
    while (slot < capacity && storage[slot].active != 0u) ++slot;
    if (slot == capacity) return 0;
    if (!index.try_emplace(value.name, slot).second) return -3;
    CCommonItem* destination = storage + slot;
    *destination = value;
    destination->active = true;
    ++item_count;
    return 0;
}
std::int32_t CItemListCommonItem::removeItem(const CItem* key) {
    if (key == nullptr) return -8;
    auto& index = item_index;
    CCommonItem* storage = item_storage.data();
    if (storage == nullptr) return -8;
    const auto found = index.find(key->name);
    if (found == index.end() || found->second >= capacity) return -8;
    const auto slot = found->second;
    index.erase(found);
    CCommonItem* removed = storage + slot;
    removed->active = false;
    removed->resetItem();
    --item_count;
    return item_count < minimum_items ? -6 : 0;
}
CItemListCommonItem* CBaseManagerCommonItem::findStoredList(const CItem* key) {
    if (key == nullptr) return nullptr;
    auto& index = item_index;
    CItemListCommonItem* storage = list_storage.data();
    if (storage == nullptr) return nullptr;
    const auto found = index.find(key->name);
    return found == index.end() || found->second >= capacity ? nullptr : storage + found->second;
}
CCommonItem* CBaseManagerCommonItem::selectItem(CCommonItem* output, const char* list_name, std::int32_t field_ac_filter, std::int32_t field_a8_filter, std::int32_t field_b0_filter) {
    if (output == nullptr) return nullptr;
    CCommonItem empty; empty.name[0] = '\0'; empty.active = false;
    CItem key; strncpy_s(key.name, sizeof(key.name), list_name == nullptr ? "" : list_name, _TRUNCATE); key.active = false;
    CItemListCommonItem* list = findStoredList(&key);
    CCommonItem* selected = &empty;
    if (list != nullptr && (field_ac_filter != -1 || field_a8_filter != -1 || field_b0_filter != -1)) {
        auto matches = [field_ac_filter, field_a8_filter, field_b0_filter](const CCommonItem& item) { return (field_ac_filter == -1 || item.field_ac == field_ac_filter) && (field_a8_filter == -1 || item.field_a8 == field_a8_filter) && (field_b0_filter == -1 || item.field_b0 == field_b0_filter); };
        std::size_t match_count = 0u;
        for (CCommonItem* item = list->firstItem(); item != nullptr; item = list->nextItem()) if (matches(*item)) ++match_count;
        if (match_count != 0u) {
            std::size_t target = static_cast<std::uint32_t>(std::rand()) % match_count;
            for (CCommonItem* item = list->firstItem(); item != nullptr; item = list->nextItem()) if (matches(*item) && target-- == 0u) { selected = item; break; }
        }
    }
    *output = *selected; return output;
}
