void SceneRenderer::sortObjects(std::int32_t first, std::int32_t last) { sceneQuickSort(g_sfera_scene_array_runtime.object_positions.data, first, last, [](const SceneSortEntry& value) { return value.key; }); }
void SceneRenderer::sortLights(std::int32_t first, std::int32_t last) { sceneQuickSort(g_sfera_light_runtime.visible_handles.data, first, last, [](const SferaLightRecord* value) { return std::fabs(value->viewer_distance_squared); }); }
